# Conventions

## Money
- Money is always an integer number of cents. Never use `float` for money.
- Percentages of an amount go through `shoplib.money.percent_of`, which rounds
  half up (0.5 of a cent rounds up). Do not use the built-in `round` for money:
  it rounds half to even.

## Errors
- Invalid arguments raise `ValueError` with a short message.
- A failed operation must leave state unchanged.

## Text output
- CSV: lines end with `\n` (never `\r\n`). Fields are quoted only when they
  contain a comma, a double quote or a newline; quotes inside a quoted field are
  doubled. The header row is always present.
- JSON: `json.dumps(obj, indent=2, sort_keys=True)` followed by one newline.
  Money stays in integer cents.

## Tests
- Tests live in `tests/`, one file per module, run with `python -m pytest -q`.
"""Shopping cart."""

from dataclasses import dataclass


@dataclass
class Line:
    sku: str
    unit_price_cents: int
    qty: int


class Cart:
    def __init__(self):
        self._lines: dict[str, Line] = {}

    def add(self, sku: str, unit_price_cents: int, qty: int = 1) -> None:
        """Add `qty` units. Adding a SKU already in the cart increases its quantity."""
        if qty <= 0:
            raise ValueError("qty must be positive")
        if unit_price_cents < 0:
            raise ValueError("price must not be negative")
        if sku in self._lines:
            self._lines[sku].qty += qty
        else:
            self._lines[sku] = Line(sku, unit_price_cents, qty)

    def remove(self, sku: str) -> None:
        if sku not in self._lines:
            raise ValueError(f"{sku} is not in the cart")
        del self._lines[sku]

    def lines(self) -> list[Line]:
        return sorted(self._lines.values(), key=lambda line: line.sku)

    def line_total(self, sku: str) -> int:
        """Total for one line in cents."""
        if sku not in self._lines:
            raise ValueError(f"{sku} is not in the cart")
        line = self._lines[sku]
        return line.unit_price_cents * line.qty

    def subtotal(self) -> int:
        """Sum of all line totals in cents."""
        return sum(self.line_total(sku) for sku in self._lines)
"""Money helpers. All money in shoplib is an integer number of cents."""

from decimal import ROUND_HALF_UP, Decimal


def round_cents(amount) -> int:
    """Round a fractional number of cents to whole cents, half up (0.5 -> 1)."""
    return int(Decimal(str(amount)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def percent_of(cents: int, percent) -> int:
    """`percent` percent of `cents`, rounded half up. Uses Decimal, not float."""
    return round_cents(Decimal(cents) * Decimal(str(percent)) / Decimal(100))


def format_money(cents: int) -> str:
    """Format cents as dollars: 1234 -> '$12.34', -5 -> '-$0.05'."""
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}${cents // 100}.{cents % 100:02d}"

import pytest

from shoplib.inventory import Inventory
from shoplib.orders import DELIVERED, NEW, Order


def make():
    inv = Inventory()
    inv.receive("A", 5)
    return inv, Order("o1", {"A": 2}, inv)


def test_happy_path():
    inv, order = make()
    assert order.state == NEW
    assert inv.available("A") == 3
    order.pay()
    order.ship()
    order.deliver()
    assert order.state == DELIVERED
    assert inv.on_hand("A") == 3


def test_cannot_ship_unpaid():
    _, order = make()
    with pytest.raises(ValueError):
        order.ship()
"""Orders and their life cycle. See docs/order-states.md."""

from .inventory import Inventory

NEW = "NEW"
PAID = "PAID"
SHIPPED = "SHIPPED"
DELIVERED = "DELIVERED"
CANCELLED = "CANCELLED"


class Order:
    def __init__(self, order_id: str, lines: dict[str, int], inventory: Inventory):
        """Create an order for `lines` (sku -> qty) and reserve its stock."""
        if not lines:
            raise ValueError("an order needs at least one line")
        self.order_id = order_id
        self.lines = dict(lines)
        self.inventory = inventory
        self.state = NEW
        self.refund_due = False
        reserved = []
        try:
            for sku, qty in self.lines.items():
                inventory.reserve(sku, qty)
                reserved.append((sku, qty))
        except ValueError:
            for sku, qty in reserved:
                inventory._reserved[sku] -= qty
            raise

    def _transition(self, allowed_from: tuple[str, ...], to: str) -> None:
        if self.state not in allowed_from:
            raise ValueError(f"cannot go from {self.state} to {to}")
        self.state = to

    def pay(self) -> None:
        self._transition((NEW,), PAID)

    def ship(self) -> None:
        if self.state != PAID:
            raise ValueError(f"cannot go from {self.state} to {SHIPPED}")
        for sku, qty in self.lines.items():
            self.inventory.ship(sku, qty)
        self.state = SHIPPED

    def deliver(self) -> None:
        self._transition((SHIPPED,), DELIVERED)
